import React, { useState, useEffect } from "react";
import MessageInput from "./components/MessageInput";   // Corrected path
import ChatWindow from "./components/ChatWindow";       // Corrected path
import LoadingIndicator from "./components/LoadingIndicator"; // Corrected path
import "./App.css";

function App() {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);

  // Fetch chat history from the backend
  useEffect(() => {
    fetch("http://localhost:5000/messages")
      .then((res) => res.json())
      .then((data) => setMessages(data));
  }, []);

  // Handle message sending
  const handleSendMessage = async (userMessage) => {
    const newMessage = { text: userMessage, sender: "user" };
    setMessages((prevMessages) => [...prevMessages, newMessage]);

    // Post user message to the server
    await fetch("http://localhost:5000/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newMessage),
    });

    // Send message to AI and get response
    setLoading(true);
    const aiResponse = await fetchDeepAIResponse(userMessage);
    setLoading(false);

    const aiMessage = { text: aiResponse, sender: "ai" };
    setMessages((prevMessages) => [...prevMessages, aiMessage]);

    // Post AI message to server
    await fetch("http:", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(aiMessage),
    });
  };

  const fetchDeepAIResponse = async (userMessage) => {
    // Mock response for DeepAI (replace with real API call)
    return "This is a response from the AI.";
  };

  return (
    <div className="App">
      <ChatWindow messages={messages} />
      {loading ? (
        <LoadingIndicator />
      ) : (
        <MessageInput onSendMessage={handleSendMessage} />
      )}
    </div>
  );
}

export default App;
